int x = 5;

// Data is const (cannot modify *p)
const int* p_data = &x;
// *p_data = 6; // Error

// Pointer is const (cannot modify p_ptr)
int* const p_ptr = &x;
// p_ptr = nullptr; // Error

// Both are const
const int* const p_both = &x;

// Const reference parameter (input only)
void print(const int& ref) {
    // ref = 10; // Error
}
