class Logger {
    mutable int access_count = 0; // Can change in const functions
    int data = 0;
public:
    // This function guarantees 'data' is not modified
    int getData() const {
        access_count++; // OK (mutable field)
        // data = 1; // Error (non-mutable field)
        return data;
    }
    void setData(int val) { data = val; }
};

const Logger c_log;
c_log.getData(); // OK
// c_log.setData(5); // Error
