// Removing constness (use with extreme caution)
void update_legacy(const int* ptr) {
    // Requires that the object was not originally defined const
    int* writable_ptr = const_cast<int*>(ptr);
    *writable_ptr = 42;
}

// Function returns a const reference
// Prevents modifying the object through the return value
const std::string& getName() {
    static std::string name = "A";
    return name;
}
